(function () {
  'use strict';

  /* =======================================================
     UTIL
  ======================================================= */
  function fmtBRL(n) { return (n || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }); }
  function uid(prefix) { return prefix + '_' + Math.random().toString(36).slice(2, 9); }
  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function clamp(n, min, max) { return Math.max(min, Math.min(max, n)); }
  function onlyDigits(s) { return String(s || '').replace(/\D/g, ''); }

  /* =======================================================
     FONTES / CATEGORIAS (mesmas do painel do lojista)
  ======================================================= */
  var FONT_OPTIONS = [
    { id: 'archivo', css: '"Archivo",sans-serif', weight: 900, transform: 'uppercase', spacing: '-.03em' },
    { id: 'anton', css: '"Anton",sans-serif', weight: 400, transform: 'uppercase', spacing: '.01em' },
    { id: 'bebas', css: '"Bebas Neue",sans-serif', weight: 400, transform: 'uppercase', spacing: '.03em' },
    { id: 'oswald', css: '"Oswald",sans-serif', weight: 700, transform: 'uppercase', spacing: '-.01em' },
    { id: 'poppins', css: '"Poppins",sans-serif', weight: 800, transform: 'none', spacing: '-.01em' },
    { id: 'space', css: '"Space Grotesk",sans-serif', weight: 700, transform: 'none', spacing: '-.02em' },
    { id: 'playfair', css: '"Playfair Display",serif', weight: 900, transform: 'none', spacing: '0', style: 'italic' },
    { id: 'dmserif', css: '"DM Serif Display",serif', weight: 400, transform: 'none', spacing: '0' },
    { id: 'fraunces', css: '"Fraunces",serif', weight: 900, transform: 'none', spacing: '0', style: 'italic' },
    { id: 'caveat', css: '"Caveat",cursive', weight: 700, transform: 'none', spacing: '0' }
  ];
  function fontById(id) { return FONT_OPTIONS.filter(function (f) { return f.id === id; })[0] || FONT_OPTIONS[0]; }
  function applyFontStyle(el, fontId) {
    var f = fontById(fontId);
    el.style.fontFamily = f.css;
    el.style.fontWeight = f.weight;
    el.style.textTransform = f.transform;
    el.style.letterSpacing = f.spacing;
    el.style.fontStyle = f.style || 'normal';
  }

  var CATEGORIAS = { roupas: 'Roupas', calcados: 'Calçados', acessorios: 'Acessórios' };
  var SUBCATEGORIAS = {
    roupas: ['Blusa', 'Camisa', 'Vestido', 'Calça', 'Saia', 'Short', 'Casaco', 'Jaqueta', 'Moletom', 'Conjunto'],
    calcados: ['Tênis', 'Sandália', 'Sapato', 'Bota', 'Chinelo'],
    acessorios: ['Bolsa', 'Cinto', 'Óculos', 'Bijuteria', 'Chapéu', 'Lenço', 'Meia']
  };
  var THUMB_COLORS = ['#ff3ec8', '#c9f231', '#5fe3f5', '#8b7cf6', '#ffb547'];
  var BRAND_LOGOS = ['Nike', 'Adidas', 'New Balance', 'Puma', 'Under Armour'];
  var SIZE_OPTIONS = {
    roupas: ['PP', 'P', 'M', 'G', 'GG'],
    calcados: ['35', '36', '37', '38', '39', '40', '41', '42'],
    acessorios: ['Único']
  };

  function normalizeSizes(value) {
    var list = Array.isArray(value) ? value : [];
    return list.map(function (size) { return String(size || '').trim(); })
      .filter(function (size) { return size; })
      .filter(function (size, index, arr) { return arr.indexOf(size) === index; });
  }
  function productSizes(product) {
    if (!product) return [];
    var sizes = normalizeSizes(product.tamanhos);
    if (sizes.length) return sizes;
    var fallback = SIZE_OPTIONS[product.categoria] || ['Único'];
    return normalizeSizes(fallback);
  }

  /* =======================================================
     SEED (usado só se ainda não existir estado do painel)
  ======================================================= */
  function seedProdutos() {
    var base = [
      ['Vestido Aurora', 'roupas', 'Vestido', 189.9, 4, 6],
      ['Vestido Pink', 'roupas', 'Vestido', 189.0, 12, 5],
      ['Calça Sol', 'roupas', 'Calça', 149.9, 18, 6],
      ['Bolsa Lua', 'acessorios', 'Bolsa', 129.9, 2, 5],
      ['Jaqueta Jeans', 'roupas', 'Jaqueta', 219.9, 9, 4],
      ['Tênis Branco', 'calcados', 'Tênis', 259.9, 14, 6],
      ['Bolsa Trança', 'acessorios', 'Bolsa', 159.9, 1, 4],
      ['Conjunto Linho', 'roupas', 'Conjunto', 279.9, 6, 5],
      ['Sandália Verão', 'calcados', 'Sandália', 139.9, 22, 6],
      ['Cinto Couro', 'acessorios', 'Cinto', 89.9, 3, 5],
      ['Blusa Tricô', 'roupas', 'Blusa', 119.9, 16, 5],
      ['Óculos Sol', 'acessorios', 'Óculos', 99.9, 0, 4]
    ];
    return base.map(function (p, i) {
      return {
        id: uid('prod'), nome: p[0], categoria: p[1], subcategoria: p[2], preco: p[3],
        estoque: p[4], estoqueMin: p[5], vendas30: 0, ultimaVendaDias: 0,
        cor: THUMB_COLORS[i % THUMB_COLORS.length], imagem: null,
        tamanhos: SIZE_OPTIONS[p[1]] || ['Único']
      };
    });
  }
  function seedCupons() {
    var now = Date.now(), day = 86400000;
    return [
      { id: uid('cup'), nome: 'BEMVINDA10', tipo: 'percentual', valor: 10, validade: new Date(now + 20 * day).toISOString(), limite: 200, limitePorCliente: 1, usos: 0, ativo: true, resultado: 0 }
    ];
  }
  function seedState() {
    return {
      storeName: 'Luna Store',
      storeFont: 'archivo',
      storeWhatsapp: '5521999998888',
      storeAddress: { rua: 'Rua das Palmeiras', numero: '245', bairro: 'Centro', cidade: 'Rio de Janeiro' },
      metaMensal: 20000,
      produtos: seedProdutos(),
      pedidos: [],
      cupons: seedCupons(),
      movimentacoes: [],
      acoesSemVenda: {}
    };
  }

  /* =======================================================
     ESTADO COMPARTILHADO (mesma chave do painel do lojista)
  ======================================================= */
  var STORAGE_KEY = 'vesthub_painel_v1';
  var state = loadState();

  function loadState() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        var defaults = seedState();
        Object.keys(defaults).forEach(function (k) { if (parsed[k] === undefined) parsed[k] = defaults[k]; });
        return parsed;
      }
    } catch (e) { /* ignore */ }
    return seedState();
  }
  function saveState() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (e) { /* ignore */ }
  }

  /* =======================================================
     CLIENTES (conta do comprador — chave própria)
  ======================================================= */
  var CUSTOMERS_KEY = 'vesthub_customers_v1';
  var SESSION_KEY = 'vesthub_customer_session_v1';

  function loadCustomers() {
    try { return JSON.parse(localStorage.getItem(CUSTOMERS_KEY) || '[]'); } catch (e) { return []; }
  }
  function saveCustomers(list) {
    try { localStorage.setItem(CUSTOMERS_KEY, JSON.stringify(list)); } catch (e) { /* ignore */ }
  }
  function currentCustomer() {
    var id = localStorage.getItem(SESSION_KEY);
    if (!id) return null;
    return loadCustomers().filter(function (c) { return c.id === id && c.ativo !== false; })[0] || null;
  }
  function setSession(id) {
    if (id) localStorage.setItem(SESSION_KEY, id); else localStorage.removeItem(SESSION_KEY);
  }

  /* =======================================================
     CARRINHO (por navegador — chave própria)
  ======================================================= */
  var CART_KEY = 'vesthub_cart_v1';
  function loadCart() {
    try { return JSON.parse(localStorage.getItem(CART_KEY) || '{"items":[],"cupom":null}'); }
    catch (e) { return { items: [], cupom: null }; }
  }
  function saveCart() { try { localStorage.setItem(CART_KEY, JSON.stringify(cart)); } catch (e) { /* ignore */ } }
  var cart = loadCart();

  function produtoById(id) { return state.produtos.filter(function (p) { return p.id === id; })[0]; }

  function cartLines() {
    return cart.items.map(function (it) {
      var p = produtoById(it.produtoId);
      return p ? { produto: p, qtd: it.qtd, tamanho: it.tamanho || null } : null;
    }).filter(Boolean);
  }
  function cartSubtotal() {
    return cartLines().reduce(function (s, l) { return s + l.produto.preco * l.qtd; }, 0);
  }
  function findCupom(nome) {
    return state.cupons.filter(function (c) { return c.nome.toLowerCase() === String(nome).toLowerCase(); })[0];
  }
  function cupomStatus(c) {
    if (!c) return null;
    if (!c.ativo) return 'desativado';
    if (new Date(c.validade).getTime() < Date.now()) return 'expirado';
    if (c.usos >= c.limite) return 'esgotado';
    return 'ativo';
  }
  function cartDiscount() {
    if (!cart.cupom) return 0;
    var c = findCupom(cart.cupom);
    if (!c || cupomStatus(c) !== 'ativo') return 0;
    var subtotal = cartSubtotal();
    var desconto = c.tipo === 'percentual' ? subtotal * (c.valor / 100) : c.valor;
    return Math.min(desconto, subtotal);
  }
  function cartTotal() { return Math.max(0, cartSubtotal() - cartDiscount()); }
  function cartCount() { return cart.items.reduce(function (s, it) { return s + it.qtd; }, 0); }

  /* =======================================================
     TOASTS
  ======================================================= */
  var toastStack = document.getElementById('toastStack');
  var ICONS = {
    success: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg>',
    danger: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M12 9v4M12 17h.01"/><path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/></svg>',
    info: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M12 16v-4M12 8h.01"/><circle cx="12" cy="12" r="9"/></svg>'
  };
  function toast(type, title, text) {
    var el = document.createElement('div');
    el.className = 'toast is-' + type;
    el.innerHTML =
      '<span class="toast-icon">' + ICONS[type] + '</span>' +
      '<span class="toast-text"><strong>' + escapeHtml(title) + '</strong>' + (text ? escapeHtml(text) : '') + '</span>' +
      '<button class="toast-close" type="button" aria-label="Fechar"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg></button>';
    toastStack.appendChild(el);
    function remove() { el.classList.add('is-leaving'); setTimeout(function () { el.remove(); }, 200); }
    el.querySelector('.toast-close').addEventListener('click', remove);
    setTimeout(remove, 5500);
  }

  /* =======================================================
     MODAL
  ======================================================= */
  var modalOverlay = document.getElementById('modalOverlay');
  var modalBody = document.getElementById('modalBody');
  document.getElementById('modalClose').addEventListener('click', closeModal);
  modalOverlay.addEventListener('click', function (e) { if (e.target === modalOverlay) closeModal(); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && !modalOverlay.hidden) closeModal(); });

  function openModal(html) {
    modalBody.innerHTML = html;
    modalOverlay.hidden = false;
    document.body.style.overflow = 'hidden';
    var first = modalBody.querySelector('input, select, button');
    if (first) setTimeout(function () { first.focus(); }, 60);
  }
  function closeModal() {
    modalOverlay.hidden = true;
    modalBody.innerHTML = '';
    document.body.style.overflow = '';
  }

  /* =======================================================
     CABEÇALHO DA LOJA (nome, fonte, conta, carrinho)
  ======================================================= */
  function renderHeader() {
    var nameEl = document.getElementById('storeName');
    nameEl.textContent = state.storeName;
    applyFontStyle(nameEl, state.storeFont);
    document.title = state.storeName + ' — VestHub';

    var customer = currentCustomer();
    document.getElementById('contaLabel').textContent = customer ? customer.nome.split(' ')[0] : 'Entrar';

    var badge = document.getElementById('cartCount');
    var count = cartCount();
    badge.hidden = count === 0;
    badge.textContent = count;
  }

  /* =======================================================
     CARROSSEL DE DESTAQUE (loop infinito)
  ======================================================= */
  var FEATURED = [
    { key: 'nike1', brand: 'Nike', caption: 'Performance em todos os momentos', categoria: 'roupas' },
    { key: 'adidas1', brand: 'Adidas', caption: 'Estilo que te move', categoria: 'roupas' },
    { key: 'newbalance', brand: 'New Balance', caption: 'Conforto e performance', categoria: 'calcados' },
    { key: 'nike2', brand: 'Nike', caption: 'Mais que roupas, é atitude', categoria: 'roupas' },
    { key: 'adidas2', brand: 'Adidas', caption: 'Tradição e inovação', categoria: 'roupas' }
  ];
  var FEATURED_IMAGES = {"nike1": "data:image/webp;base64,", "adidas1": "data:image/webp;base64,", "newbalance": "data:image/webp;base64,", "nike2": "data:image/webp;base64,", "adidas2": "data:image/webp;base64,"};

  function initFeaturedCarousel() {
    var track = document.getElementById('fcTrack');
    var dotsBox = document.getElementById('fcDots');
    var viewport = track.parentElement;
    var real = FEATURED.length;

    track.innerHTML = FEATURED.map(function (f, i) {
      return '<button class="fc-slide" type="button" data-categoria="' + f.categoria + '" data-index="' + i + '">' +
        '<img src="' + FEATURED_IMAGES[f.key] + '" alt="' + escapeHtml(f.brand) + '" loading="' + (i < 2 ? 'eager' : 'lazy') + '">' +
        '<span class="fc-caption"><strong>' + escapeHtml(f.brand) + '</strong><span>' + escapeHtml(f.caption) + '</span></span>' +
        '</button>';
    }).join('');

    [-1, 1].forEach(function (side) {
      FEATURED.forEach(function (f, i) {
        var clone = track.children[i].cloneNode(true);
        clone.setAttribute('aria-hidden', 'true');
        clone.tabIndex = -1;
        side < 0 ? track.insertBefore(clone, track.firstChild) : track.appendChild(clone);
      });
    });
    var slides = Array.prototype.slice.call(track.children);
    var index = real;

    FEATURED.forEach(function (f, i) {
      var dot = document.createElement('button');
      dot.type = 'button';
      dot.className = 'fc-dot';
      dot.setAttribute('aria-label', 'Ir para o destaque ' + (i + 1));
      dot.addEventListener('click', function () { go(real + i); stop(); });
      dotsBox.appendChild(dot);
    });
    var dots = Array.prototype.slice.call(dotsBox.children);

    function current() { return ((index % real) + real) % real; }
    function layout(animate) {
      var w = slides[0].offsetWidth + 16; /* largura + margin-inline total */
      if (!animate) track.style.transition = 'none';
      track.style.transform = 'translateX(' + (viewport.clientWidth / 2 - w / 2 - index * w) + 'px)';
      if (!animate) { void track.offsetWidth; track.style.transition = ''; }
      slides.forEach(function (s, i) { s.classList.toggle('is-active', i === index); });
      dots.forEach(function (d, i) { d.classList.toggle('is-active', i === current()); });
    }
    track.addEventListener('transitionend', function () {
      if (index < real || index >= real * 2) { index = real + current(); layout(false); }
    });
    function go(i) { index = i; layout(true); }

    slides.forEach(function (slide, i) {
      slide.addEventListener('click', function () {
        if (i !== index) { go(i); stop(); return; }
        var categoria = slide.dataset.categoria;
        selectCategoria(categoria);
        document.getElementById('catalogo').scrollIntoView({ behavior: 'smooth', block: 'start' });
      });
    });

    document.getElementById('fcPrev').addEventListener('click', function () { go(index - 1); stop(); });
    document.getElementById('fcNext').addEventListener('click', function () { go(index + 1); stop(); });

    var startX = null;
    viewport.addEventListener('pointerdown', function (e) { startX = e.clientX; });
    viewport.addEventListener('pointerup', function (e) {
      if (startX === null) return;
      var dx = e.clientX - startX;
      if (Math.abs(dx) > 40) { go(index + (dx < 0 ? 1 : -1)); stop(); }
      startX = null;
    });

    var timer = null;
    var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
    function start() { if (!reduce.matches && !timer) timer = setInterval(function () { go(index + 1); }, 4500); }
    function stop() { clearInterval(timer); timer = null; }
    viewport.addEventListener('mouseenter', stop);
    viewport.addEventListener('mouseleave', start);

    window.addEventListener('resize', function () { layout(false); });
    layout(false);
    start();
  }

  /* =======================================================
     CATÁLOGO (categoria / subcategoria / grid)
  ======================================================= */
  var filtroCategoria = 'todas';
  var filtroSubcategoria = 'todas';

  function selectCategoria(cat) {
    filtroCategoria = cat;
    filtroSubcategoria = 'todas';
    renderCategoryNav();
    renderSubcategoryNav();
    renderProductGrid();
  }

  function renderCategoryNav() {
    var box = document.getElementById('categoryNav');
    var cats = ['todas'].concat(Object.keys(CATEGORIAS));
    box.innerHTML = cats.map(function (c) {
      var label = c === 'todas' ? 'Todas' : CATEGORIAS[c];
      return '<button type="button" class="cat-pill' + (filtroCategoria === c ? ' is-active' : '') + '" data-cat="' + c + '">' + label + '</button>';
    }).join('');
    Array.prototype.forEach.call(box.children, function (btn) {
      btn.addEventListener('click', function () { selectCategoria(btn.dataset.cat); });
    });
  }

  function renderSubcategoryNav() {
    var box = document.getElementById('subcategoryNav');
    if (filtroCategoria === 'todas') { box.innerHTML = ''; return; }
    var subs = SUBCATEGORIAS[filtroCategoria] || [];
    box.innerHTML = '<button type="button" class="subcat-pill' + (filtroSubcategoria === 'todas' ? ' is-active' : '') + '" data-sub="todas">Todas</button>' +
      subs.map(function (s) {
        return '<button type="button" class="subcat-pill' + (filtroSubcategoria === s ? ' is-active' : '') + '" data-sub="' + escapeHtml(s) + '">' + escapeHtml(s) + '</button>';
      }).join('');
    Array.prototype.forEach.call(box.children, function (btn) {
      btn.addEventListener('click', function () { filtroSubcategoria = btn.dataset.sub; renderSubcategoryNav(); renderProductGrid(); });
    });
  }

  function buildProductThumb(p) {
    if (p.imagem) return '<img src="' + p.imagem + '" alt="">';
    var letter = (p.subcategoria || p.nome || '?').charAt(0).toUpperCase();
    return '<span class="product-thumb-letter" style="background:linear-gradient(145deg,#f7f6f4,#ece9e4);width:100%;height:100%;display:flex;align-items:center;justify-content:center">' + letter + '</span>';
  }

  function renderBrandCarousel() {
    var brandMarkup = BRAND_LOGOS.map(function (brand) {
      return '<div class="brand-logo" aria-label="Marca ' + escapeHtml(brand) + '">' + escapeHtml(brand) + '</div>';
    }).join('');
    return '<div class="brand-carousel" aria-label="Marcas em destaque">' +
      '<div class="brand-carousel-head"><span>Marcas</span><div class="brand-carousel-controls">' +
      '<button type="button" class="brand-arrow" data-brand-dir="prev" aria-label="Anterior"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M15 5 8 12l7 7"/></svg></button>' +
      '<button type="button" class="brand-arrow" data-brand-dir="next" aria-label="Próximo"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="m9 5 7 7-7 7"/></svg></button>' +
      '</div></div>' +
      '<div class="brand-track" id="brandTrack">' + brandMarkup + '</div>' +
      '</div>';
  }

  function renderProductGrid() {
    var lista = state.produtos.slice();
    if (filtroCategoria !== 'todas') lista = lista.filter(function (p) { return p.categoria === filtroCategoria; });
    if (filtroSubcategoria !== 'todas') lista = lista.filter(function (p) { return p.subcategoria === filtroSubcategoria; });
    var searchInput = document.getElementById('storeSearchInput');
    var q = searchInput ? searchInput.value.trim().toLowerCase() : '';
    if (q) {
      lista = lista.filter(function (p) {
        var term = [p.nome, p.categoria, p.subcategoria, productSizes(p).join(' ')].join(' ').toLowerCase();
        return term.indexOf(q) !== -1;
      });
    }

    var grid = document.getElementById('productGrid');
    var empty = document.getElementById('catalogEmpty');
    if (!lista.length) { grid.innerHTML = ''; empty.hidden = false; return; }
    empty.hidden = true;

    var cards = [];
    lista.forEach(function (p, index) {
      if (index === 8) cards.push(renderBrandCarousel());
      var esgotado = p.estoque <= 0;
      var flag = esgotado ? '<span class="product-stock-flag is-out">Esgotado</span>' :
        (p.estoque <= p.estoqueMin ? '<span class="product-stock-flag">Últimas unidades</span>' : '');
      cards.push('<article class="product-card">' +
        '<div class="product-thumb">' + buildProductThumb(p) + flag + '</div>' +
        '<div class="product-info">' +
        '<span class="product-cat">' + (p.subcategoria || CATEGORIAS[p.categoria] || '') + '</span>' +
        '<h3 class="product-name">' + escapeHtml(p.nome) + '</h3>' +
        '<span class="product-price">' + fmtBRL(p.preco) + '</span>' +
        '<button class="product-add" type="button" data-add="' + p.id + '"' + (esgotado ? ' disabled' : '') + '>' + (esgotado ? 'Esgotado' : 'Adicionar') + '</button>' +
        '</div></article>');
    });
    grid.innerHTML = cards.join('');

    Array.prototype.forEach.call(grid.querySelectorAll('[data-add]'), function (btn) {
      btn.addEventListener('click', function () { addToCart(btn.dataset.add); });
    });

    var track = document.getElementById('brandTrack');
    if (track) {
      var dirButtons = grid.querySelectorAll('[data-brand-dir]');
      Array.prototype.forEach.call(dirButtons, function (btn) {
        btn.addEventListener('click', function () {
          var delta = btn.dataset.brandDir === 'next' ? 220 : -220;
          track.scrollBy({ left: delta, behavior: 'smooth' });
        });
      });
    }
  }

  /* =======================================================
     CARRINHO — ações
  ======================================================= */
  function cartLineKey(item) {
    return (item.produtoId || '') + ':' + (item.tamanho || 'Único');
  }
  function findCartLine(produtoId, tamanho) {
    var target = tamanho || 'Único';
    return cart.items.filter(function (it) { return it.produtoId === produtoId && (it.tamanho || 'Único') === target; })[0];
  }

  function selectProductSize(product, onSelect) {
    var sizes = productSizes(product);
    if (!sizes.length) { onSelect(null); return; }
    if (sizes.length === 1) { onSelect(sizes[0]); return; }

    openModal(
      '<h2 class="modal-title">Escolha o tamanho</h2>' +
      '<p class="modal-sub">Selecione o tamanho ideal para ' + escapeHtml(product.nome) + '.</p>' +
      '<div class="size-picker" id="sizePicker">' + sizes.map(function (size) {
        return '<label class="size-option"><input type="radio" name="size-choice" value="' + escapeHtml(size) + '"><span>' + escapeHtml(size) + '</span></label>';
      }).join('') + '</div>' +
      '<div class="modal-actions"><button class="btn btn--solid btn--full" type="button" id="confirmSize">Confirmar tamanho</button></div>'
    );

    var labels = Array.prototype.slice.call(document.querySelectorAll('.size-option'));
    labels.forEach(function (label) {
      label.addEventListener('click', function () {
        labels.forEach(function (item) { item.classList.toggle('is-selected', item === label); });
      });
    });

    document.getElementById('confirmSize').addEventListener('click', function () {
      var selected = document.querySelector('input[name="size-choice"]:checked');
      var size = selected ? selected.value : sizes[0];
      closeModal();
      onSelect(size);
    });
  }

  function addToCart(produtoId) {
    var p = produtoById(produtoId);
    if (!p || p.estoque <= 0) return;

    function commitAdd(tamanho) {
      var line = findCartLine(produtoId, tamanho);
      var qtdAtual = line ? line.qtd : 0;
      if (qtdAtual >= p.estoque) { toast('info', 'Estoque limitado', 'Não há mais unidades de "' + p.nome + '".'); return; }
      if (line) line.qtd += 1; else cart.items.push({ produtoId: produtoId, tamanho: tamanho || 'Único', qtd: 1 });
      saveCart();
      renderHeader();
      toast('success', 'Adicionado ao carrinho', p.nome + (tamanho ? ' · Tamanho ' + tamanho : ''));
      openCart();
    }

    var sizes = productSizes(p);
    if (sizes.length > 1) {
      selectProductSize(p, commitAdd);
      return;
    }
    commitAdd(sizes[0] || null);
  }

  function changeQty(produtoId, tamanho, delta) {
    var line = findCartLine(produtoId, tamanho);
    if (!line) return;
    var p = produtoById(produtoId);
    line.qtd = clamp(line.qtd + delta, 0, p ? p.estoque : 99);
    if (line.qtd <= 0) cart.items = cart.items.filter(function (it) { return cartLineKey(it) !== cartLineKey(line); });
    saveCart();
    renderCartDrawer();
    renderHeader();
    renderProductGrid();
  }
  function removeFromCart(produtoId, tamanho) {
    cart.items = cart.items.filter(function (it) { return !(it.produtoId === produtoId && (it.tamanho || 'Único') === (tamanho || 'Único')); });
    saveCart();
    renderCartDrawer();
    renderHeader();
    renderProductGrid();
  }

  var cartDrawer = document.getElementById('cartDrawer');
  var cartOverlay = document.getElementById('cartOverlay');
  function openCart() {
    renderCartDrawer();
    cartOverlay.hidden = false;
    cartDrawer.classList.add('is-open');
    document.body.style.overflow = 'hidden';
  }
  function closeCart() {
    cartDrawer.classList.remove('is-open');
    document.body.style.overflow = '';
    setTimeout(function () { cartOverlay.hidden = true; }, 300);
  }
  document.getElementById('btnCarrinho').addEventListener('click', openCart);
  document.getElementById('cartClose').addEventListener('click', closeCart);
  cartOverlay.addEventListener('click', closeCart);

  function renderCartDrawer() {
    var lines = cartLines();
    var itemsBox = document.getElementById('cartItems');
    var empty = document.getElementById('cartEmpty');
    var footer = document.getElementById('cartFooter');

    if (!lines.length) {
      itemsBox.innerHTML = '';
      empty.hidden = false;
      footer.hidden = true;
      return;
    }
    empty.hidden = true;
    footer.hidden = false;

    itemsBox.innerHTML = lines.map(function (l) {
      var thumb = l.produto.imagem
        ? '<img class="cart-item-thumb" src="' + l.produto.imagem + '" alt="">'
        : '<span class="cart-item-thumb" style="background:linear-gradient(145deg,#f7f6f4,#ece9e4)"></span>';
      var sizeHint = l.tamanho ? '<span class="cart-item-meta">Tamanho: ' + escapeHtml(l.tamanho) + '</span>' : '';
      return '<div class="cart-item">' + thumb +
        '<div class="cart-item-body">' +
        '<p class="cart-item-name">' + escapeHtml(l.produto.nome) + '</p>' +
        '<span class="cart-item-price">' + fmtBRL(l.produto.preco) + '</span>' + sizeHint +
        '<div class="cart-item-actions">' +
        '<div class="qty-stepper">' +
        '<button type="button" data-qty="' + l.produto.id + '" data-size="' + escapeHtml(l.tamanho || 'Único') + '" data-delta="-1">−</button>' +
        '<span>' + l.qtd + '</span>' +
        '<button type="button" data-qty="' + l.produto.id + '" data-size="' + escapeHtml(l.tamanho || 'Único') + '" data-delta="1">+</button>' +
        '</div>' +
        '<button class="cart-item-remove" type="button" data-remove="' + l.produto.id + '" data-size="' + escapeHtml(l.tamanho || 'Único') + '" aria-label="Remover">' +
        '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6"/></svg>' +
        '</button></div></div></div>';
    }).join('');

    Array.prototype.forEach.call(itemsBox.querySelectorAll('[data-qty]'), function (btn) {
      btn.addEventListener('click', function () { changeQty(btn.dataset.qty, btn.dataset.size || 'Único', Number(btn.dataset.delta)); });
    });
    Array.prototype.forEach.call(itemsBox.querySelectorAll('[data-remove]'), function (btn) {
      btn.addEventListener('click', function () { removeFromCart(btn.dataset.remove, btn.dataset.size || 'Único'); });
    });

    document.getElementById('cartSubtotal').textContent = fmtBRL(cartSubtotal());
    var discount = cartDiscount();
    var discountRow = document.getElementById('cartDiscountRow');
    discountRow.hidden = discount <= 0;
    document.getElementById('cartDiscount').textContent = '− ' + fmtBRL(discount);
    document.getElementById('cartTotal').textContent = fmtBRL(cartTotal());

    var appliedBox = document.getElementById('cupomApplied');
    if (cart.cupom && discount > 0) {
      appliedBox.hidden = false;
      appliedBox.innerHTML = '<span>Cupom "' + escapeHtml(cart.cupom) + '" aplicado</span><button type="button" id="removerCupom">remover</button>';
      document.getElementById('removerCupom').addEventListener('click', function () {
        cart.cupom = null; saveCart(); renderCartDrawer();
      });
      document.getElementById('cupomInput').value = '';
    } else {
      appliedBox.hidden = true;
    }
  }

  document.getElementById('cupomApply').addEventListener('click', function () {
    var input = document.getElementById('cupomInput');
    var msg = document.getElementById('cupomMsg');
    var nome = input.value.trim();
    if (!nome) return;
    var c = findCupom(nome);
    var status = cupomStatus(c);
    if (!c) { msg.textContent = 'Cupom não encontrado.'; return; }
    if (status === 'expirado') { msg.textContent = 'Esse cupom expirou.'; return; }
    if (status === 'desativado') { msg.textContent = 'Esse cupom não está mais ativo.'; return; }
    if (status === 'esgotado') { msg.textContent = 'Esse cupom já atingiu o limite de usos.'; return; }
    msg.textContent = '';
    cart.cupom = c.nome;
    saveCart();
    renderCartDrawer();
    toast('success', 'Cupom aplicado', c.nome);
  });

  /* =======================================================
     CONTA DO CLIENTE (cadastro / login)
  ======================================================= */
  function openAccountModal() {
    var customer = currentCustomer();
    if (customer) { openAccountPanel(customer); return; }

    openModal(
      '<div class="modal-tabs" id="accTabs">' +
      '<button type="button" class="is-active" data-tab="entrar">Entrar</button>' +
      '<button type="button" data-tab="cadastro">Criar conta</button>' +
      '</div>' +
      '<div id="accTabBody"></div>'
    );
    renderLoginTab();
    document.getElementById('accTabs').addEventListener('click', function (e) {
      var btn = e.target.closest('button[data-tab]');
      if (!btn) return;
      Array.prototype.forEach.call(this.children, function (b) { b.classList.toggle('is-active', b === btn); });
      btn.dataset.tab === 'entrar' ? renderLoginTab() : renderCadastroTab();
    });
  }

  function renderLoginTab() {
    document.getElementById('accTabBody').innerHTML =
      '<h2 class="modal-title">Que bom te ver de novo!</h2>' +
      '<p class="modal-sub">Entre para acompanhar seus pedidos.</p>' +
      '<form id="loginForm">' +
      '<div class="form-row"><label for="loginEmail">E-mail</label><input type="email" id="loginEmail" required></div>' +
      '<div class="form-row"><label for="loginSenha">Senha</label><input type="password" id="loginSenha" required></div>' +
      '<span class="field-error" id="loginError"></span>' +
      '<div class="modal-actions" style="justify-content:stretch">' +
      '<button class="btn btn--solid btn--full" type="submit">Entrar</button>' +
      '</div></form>';
    document.getElementById('loginForm').addEventListener('submit', function (e) {
      e.preventDefault();
      var email = document.getElementById('loginEmail').value.trim().toLowerCase();
      var senha = document.getElementById('loginSenha').value;
      var cliente = loadCustomers().filter(function (c) { return c.email.toLowerCase() === email && c.senha === senha && c.ativo !== false; })[0];
      if (!cliente) { document.getElementById('loginError').textContent = 'E-mail ou senha incorretos.'; return; }
      setSession(cliente.id);
      renderHeader();
      closeModal();
      toast('success', 'Bem-vinda(o) de volta!', cliente.nome);
    });
  }

  function renderCadastroTab() {
    document.getElementById('accTabBody').innerHTML =
      '<h2 class="modal-title">Criar minha conta</h2>' +
      '<p class="modal-sub">Agiliza suas próximas compras nesta loja.</p>' +
      '<form id="cadastroClienteForm">' +
      '<div class="form-row"><label for="ccNome">Nome completo</label><input type="text" id="ccNome" required></div>' +
      '<div class="form-row"><label for="ccWhats">WhatsApp</label><input type="tel" id="ccWhats" placeholder="(21) 90000-0000" required></div>' +
      '<div class="form-row"><label for="ccEmail">E-mail</label><input type="email" id="ccEmail" required></div>' +
      '<div class="form-row"><label for="ccSenha">Senha</label><input type="password" id="ccSenha" minlength="6" required></div>' +
      '<div class="modal-actions" style="justify-content:stretch">' +
      '<button class="btn btn--solid btn--full" type="submit">Criar conta</button>' +
      '</div></form>';
    document.getElementById('cadastroClienteForm').addEventListener('submit', function (e) {
      e.preventDefault();
      var nome = document.getElementById('ccNome').value.trim();
      var whats = onlyDigits(document.getElementById('ccWhats').value);
      var email = document.getElementById('ccEmail').value.trim().toLowerCase();
      var senha = document.getElementById('ccSenha').value;
      if (!nome || !whats || !email || senha.length < 6) return;
      var list = loadCustomers();
      if (list.some(function (c) { return c.email.toLowerCase() === email; })) {
        toast('danger', 'E-mail já cadastrado', 'Tente entrar com sua conta existente.');
        return;
      }
      var novo = { id: uid('cli'), nome: nome, whatsapp: whats, email: email, senha: senha, endereco: null, ativo: true };
      list.push(novo);
      saveCustomers(list);
      setSession(novo.id);
      renderHeader();
      closeModal();
      toast('success', 'Conta criada!', 'Boas compras, ' + nome.split(' ')[0] + '.');
    });
  }

  function openAccountEditModal(customer) {
    openModal(
      '<h2 class="modal-title">Editar meus dados</h2>' +
      '<p class="modal-sub">Atualize suas informações de contato.</p>' +
      '<form id="accountEditForm">' +
      '<div class="form-row"><label for="editNome">Nome completo</label><input type="text" id="editNome" value="' + escapeHtml(customer.nome) + '" required></div>' +
      '<div class="form-row"><label for="editWhats">WhatsApp</label><input type="tel" id="editWhats" value="' + escapeHtml(customer.whatsapp) + '" placeholder="(21) 90000-0000" required></div>' +
      '<div class="form-row"><label for="editEmail">E-mail</label><input type="email" id="editEmail" value="' + escapeHtml(customer.email) + '" required></div>' +
      '<div class="form-row"><label for="editSenha">Nova senha</label><input type="password" id="editSenha" minlength="6" placeholder="Deixe em branco para manter a atual"></div>' +
      '<div class="modal-actions" style="justify-content:stretch">' +
      '<button class="btn btn--solid btn--full" type="submit">Salvar alterações</button>' +
      '</div></form>'
    );

    document.getElementById('accountEditForm').addEventListener('submit', function (e) {
      e.preventDefault();
      var list = loadCustomers();
      var index = list.findIndex(function (c) { return c.id === customer.id; });
      if (index === -1) return;

      var nome = document.getElementById('editNome').value.trim();
      var whats = onlyDigits(document.getElementById('editWhats').value);
      var email = document.getElementById('editEmail').value.trim().toLowerCase();
      var senha = document.getElementById('editSenha').value;
      if (!nome || !whats || !email || (senha && senha.length < 6)) return;

      var emailDuplicado = list.some(function (c) { return c.id !== customer.id && c.email.toLowerCase() === email; });
      if (emailDuplicado) {
        toast('danger', 'E-mail em uso', 'Esse endereço já está cadastrado em outra conta.');
        return;
      }

      list[index].nome = nome;
      list[index].whatsapp = whats;
      list[index].email = email;
      if (senha) list[index].senha = senha;
      saveCustomers(list);
      closeModal();
      openAccountPanel(list[index]);
      toast('success', 'Dados atualizados', 'Suas informações foram salvas.');
    });
  }

  function deactivateAccount(customer) {
    var list = loadCustomers();
    var index = list.findIndex(function (c) { return c.id === customer.id; });
    if (index === -1) return;
    list[index].ativo = false;
    saveCustomers(list);
    setSession(null);
    renderHeader();
    closeModal();
    toast('info', 'Conta desativada', 'Você pode criar outra conta quando quiser.');
  }

  function openAccountPanel(customer) {
    var meusPedidos = state.pedidos.filter(function (p) { return onlyDigits(p.whatsapp || '') === customer.whatsapp; })
      .sort(function (a, b) { return new Date(b.data) - new Date(a.data); }).slice(0, 5);

    var pedidosHtml = meusPedidos.length ? meusPedidos.map(function (p) {
      return '<div class="order-summary-item"><span>' + p.id + ' · ' + STATUS_LABEL[p.status] + '</span><span>' + fmtBRL(p.total) + '</span></div>';
    }).join('') : '<p class="form-hint">Você ainda não fez pedidos nesta loja.</p>';

    openModal(
      '<h2 class="modal-title">Olá, ' + escapeHtml(customer.nome.split(' ')[0]) + '</h2>' +
      '<p class="modal-sub">' + escapeHtml(customer.email) + '</p>' +
      '<div class="order-summary">' + pedidosHtml + '</div>' +
      '<div class="modal-actions" style="justify-content:stretch;flex-direction:column;align-items:stretch">' +
      '<button class="btn btn--full" type="button" id="btnEditarConta">Editar meus dados</button>' +
      '<button class="btn btn--full" type="button" id="btnDesativarConta" style="margin-top:8px;border-color:var(--danger);color:var(--danger)">Desativar conta</button>' +
      '<button class="btn btn--full" type="button" id="btnSair" style="margin-top:8px">Sair da conta</button>' +
      '</div>'
    );

    document.getElementById('btnEditarConta').addEventListener('click', function () {
      closeModal();
      openAccountEditModal(customer);
    });
    document.getElementById('btnDesativarConta').addEventListener('click', function () {
      if (window.confirm('Deseja realmente desativar sua conta? Você poderá criar outra conta depois.')) {
        deactivateAccount(customer);
      }
    });
    document.getElementById('btnSair').addEventListener('click', function () {
      setSession(null);
      renderHeader();
      closeModal();
      toast('info', 'Até logo!', '');
    });
  }

  document.getElementById('btnConta').addEventListener('click', openAccountModal);

  /* =======================================================
     CHECKOUT (identificação → entrega/retirada → revisão)
  ======================================================= */
  var STATUS_LABEL = { pendente: 'Pendente', preparo: 'Em preparo', enviado: 'Enviado', entregue: 'Entregue', cancelado: 'Cancelado' };
  var checkout = { nome: '', whatsapp: '', tipoEntrega: null, endereco: null };

  function startCheckout() {
    if (!cartLines().length) return;
    var customer = currentCustomer();
    checkout = {
      nome: customer ? customer.nome : '',
      whatsapp: customer ? customer.whatsapp : '',
      tipoEntrega: null,
      endereco: customer && customer.endereco ? customer.endereco : null
    };
    closeCart();
    setTimeout(function () { renderCheckoutStep1(); }, 200);
  }
  document.getElementById('btnFinalizar').addEventListener('click', startCheckout);

  function checkoutSteps(activeIndex) {
    var labels = [0, 1, 2];
    return '<div class="checkout-steps">' + labels.map(function (i) {
      return '<span class="' + (i < activeIndex ? 'is-done' : i === activeIndex ? 'is-active' : '') + '"></span>';
    }).join('') + '</div>';
  }

  function renderCheckoutStep1() {
    openModal(
      checkoutSteps(0) +
      '<h2 class="modal-title">Seus dados</h2>' +
      '<p class="modal-sub">Usamos para confirmar seu pedido pelo WhatsApp.</p>' +
      '<form id="dadosForm">' +
      '<div class="form-row"><label for="chkNome">Nome completo</label><input type="text" id="chkNome" required value="' + escapeHtml(checkout.nome) + '"></div>' +
      '<div class="form-row"><label for="chkWhats">WhatsApp</label><input type="tel" id="chkWhats" placeholder="(21) 90000-0000" required value="' + escapeHtml(checkout.whatsapp) + '"></div>' +
      '<div class="modal-actions" style="justify-content:stretch">' +
      '<button class="btn btn--solid btn--full" type="submit">Continuar</button>' +
      '</div></form>'
    );
    document.getElementById('dadosForm').addEventListener('submit', function (e) {
      e.preventDefault();
      checkout.nome = document.getElementById('chkNome').value.trim();
      checkout.whatsapp = onlyDigits(document.getElementById('chkWhats').value);
      if (!checkout.nome || !checkout.whatsapp) return;
      renderCheckoutStep2();
    });
  }

  function renderCheckoutStep2() {
    openModal(
      checkoutSteps(1) +
      '<h2 class="modal-title">Entrega ou retirada?</h2>' +
      '<p class="modal-sub">Como você quer receber seu pedido.</p>' +
      '<div class="delivery-options" id="deliveryOptions">' +
      '<button type="button" class="delivery-option" data-tipo="retirada">' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m3 9.5 9-6.5 9 6.5"/><path d="M5 10v9a1 1 0 0 0 1 1h4v-6h4v6h4a1 1 0 0 0 1-1v-9"/></svg>' +
      '<span><strong>Retirar na loja</strong><span>' + escapeHtml(state.storeAddress.rua) + ', ' + escapeHtml(state.storeAddress.numero) + '</span></span>' +
      '</button>' +
      '<button type="button" class="delivery-option" data-tipo="entrega">' +
      '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7h11v9H3z"/><path d="M14 10h4l3 3v3h-7z"/><circle cx="7.5" cy="18.5" r="1.5"/><circle cx="17.5" cy="18.5" r="1.5"/></svg>' +
      '<span><strong>Receber em casa</strong><span>Confirme o endereço de entrega</span></span>' +
      '</button>' +
      '</div>' +
      '<div class="modal-actions"><button class="btn" type="button" id="voltarStep1">Voltar</button></div>'
    );
    document.getElementById('voltarStep1').addEventListener('click', renderCheckoutStep1);
    Array.prototype.forEach.call(document.querySelectorAll('#deliveryOptions .delivery-option'), function (btn) {
      btn.addEventListener('click', function () {
        checkout.tipoEntrega = btn.dataset.tipo;
        btn.dataset.tipo === 'retirada' ? renderCheckoutRetirada() : renderCheckoutEndereco();
      });
    });
  }

  function renderCheckoutRetirada() {
    var a = state.storeAddress;
    openModal(
      checkoutSteps(2) +
      '<h2 class="modal-title">Retirar na loja</h2>' +
      '<p class="modal-sub">Você recebe um aviso assim que estiver pronto.</p>' +
      '<div class="store-address-card"><strong>Endereço da loja</strong>' + escapeHtml(a.rua) + ', ' + escapeHtml(a.numero) + '<br>' + escapeHtml(a.bairro) + ' · ' + escapeHtml(a.cidade) + '</div>' +
      renderOrderSummaryHtml() +
      '<div class="modal-actions">' +
      '<button class="btn" type="button" id="voltarStep2">Voltar</button>' +
      '<button class="btn btn--solid" type="button" id="confirmarPedido">Confirmar e enviar no WhatsApp</button>' +
      '</div>'
    );
    document.getElementById('voltarStep2').addEventListener('click', renderCheckoutStep2);
    document.getElementById('confirmarPedido').addEventListener('click', function () { finalizarPedido(); });
  }

  function renderCheckoutEndereco() {
    var e = checkout.endereco || {};
    openModal(
      checkoutSteps(2) +
      '<h2 class="modal-title">Endereço de entrega</h2>' +
      '<p class="modal-sub">Confirme para onde enviamos seu pedido.</p>' +
      '<form id="enderecoChkForm">' +
      '<div class="form-row-split">' +
      '<div class="form-row"><label for="eRua">Rua</label><input type="text" id="eRua" required value="' + escapeHtml(e.rua || '') + '"></div>' +
      '<div class="form-row"><label for="eNumero">Número</label><input type="text" id="eNumero" required value="' + escapeHtml(e.numero || '') + '"></div>' +
      '</div>' +
      '<div class="form-row-split">' +
      '<div class="form-row"><label for="eBairro">Bairro</label><input type="text" id="eBairro" required value="' + escapeHtml(e.bairro || '') + '"></div>' +
      '<div class="form-row"><label for="eCidade">Cidade</label><input type="text" id="eCidade" required value="' + escapeHtml(e.cidade || '') + '"></div>' +
      '</div>' +
      '<div class="form-row"><label for="eComplemento">Complemento (opcional)</label><input type="text" id="eComplemento" value="' + escapeHtml(e.complemento || '') + '"></div>' +
      '<div class="modal-actions">' +
      '<button class="btn" type="button" id="voltarStep2b">Voltar</button>' +
      '<button class="btn btn--solid" type="submit">Continuar</button>' +
      '</div></form>'
    );
    document.getElementById('voltarStep2b').addEventListener('click', renderCheckoutStep2);
    document.getElementById('enderecoChkForm').addEventListener('submit', function (ev) {
      ev.preventDefault();
      checkout.endereco = {
        rua: document.getElementById('eRua').value.trim(),
        numero: document.getElementById('eNumero').value.trim(),
        bairro: document.getElementById('eBairro').value.trim(),
        cidade: document.getElementById('eCidade').value.trim(),
        complemento: document.getElementById('eComplemento').value.trim()
      };
      renderCheckoutRevisao();
    });
  }

  function renderCheckoutRevisao() {
    var e = checkout.endereco;
    openModal(
      checkoutSteps(2) +
      '<h2 class="modal-title">Confirmar entrega</h2>' +
      '<p class="modal-sub">Revise o endereço antes de enviar.</p>' +
      '<div class="store-address-card"><strong>Entregar em</strong>' + escapeHtml(e.rua) + ', ' + escapeHtml(e.numero) + (e.complemento ? ' — ' + escapeHtml(e.complemento) : '') + '<br>' + escapeHtml(e.bairro) + ' · ' + escapeHtml(e.cidade) + '</div>' +
      renderOrderSummaryHtml() +
      '<div class="modal-actions">' +
      '<button class="btn" type="button" id="voltarEndereco">Editar endereço</button>' +
      '<button class="btn btn--solid" type="button" id="confirmarPedido">Confirmar e enviar no WhatsApp</button>' +
      '</div>'
    );
    document.getElementById('voltarEndereco').addEventListener('click', renderCheckoutEndereco);
    document.getElementById('confirmarPedido').addEventListener('click', function () { finalizarPedido(); });
  }

  function renderOrderSummaryHtml(pedidoFixo) {
    var itemsHtml, subtotal, discount, total, cupomNome;
    if (pedidoFixo) {
      itemsHtml = pedidoFixo.itens.map(function (it) {
        var label = it.produto + (it.tamanho ? ' · Tamanho ' + it.tamanho : '');
        return '<div class="order-summary-item"><span>' + it.qtd + 'x ' + escapeHtml(label) + '</span><span>' + fmtBRL(it.preco * it.qtd) + '</span></div>';
      }).join('');
      subtotal = pedidoFixo.subtotal; discount = pedidoFixo.desconto; total = pedidoFixo.total; cupomNome = pedidoFixo.cupom;
    } else {
      var lines = cartLines();
      itemsHtml = lines.map(function (l) {
        var label = l.produto.nome + (l.tamanho ? ' · Tamanho ' + l.tamanho : '');
        return '<div class="order-summary-item"><span>' + l.qtd + 'x ' + escapeHtml(label) + '</span><span>' + fmtBRL(l.produto.preco * l.qtd) + '</span></div>';
      }).join('');
      subtotal = cartSubtotal(); discount = cartDiscount(); total = cartTotal(); cupomNome = cart.cupom;
    }
    return '<div class="order-summary">' + itemsHtml + '<hr>' +
      '<div class="order-summary-item"><span>Subtotal</span><span>' + fmtBRL(subtotal) + '</span></div>' +
      (discount > 0 ? '<div class="order-summary-item"><span>Cupom ' + escapeHtml(cupomNome) + '</span><span>− ' + fmtBRL(discount) + '</span></div>' : '') +
      '<div class="total-row"><span>Total</span><span>' + fmtBRL(total) + '</span></div></div>';
  }

  function buildWhatsappMessage(pedido) {
    var linhas = [];
    linhas.push('Olá, ' + state.storeName + '! Quero fazer o pedido ' + pedido.id + ':');
    linhas.push('');
    pedido.itens.forEach(function (it) {
      var label = it.produto + (it.tamanho ? ' · Tamanho ' + it.tamanho : '');
      linhas.push('• ' + it.qtd + 'x ' + label + ' — ' + fmtBRL(it.preco * it.qtd));
    });
    linhas.push('');
    if (pedido.desconto > 0) linhas.push('Subtotal: ' + fmtBRL(pedido.subtotal));
    if (pedido.desconto > 0) linhas.push('Cupom ' + pedido.cupom + ': − ' + fmtBRL(pedido.desconto));
    linhas.push('Total: ' + fmtBRL(pedido.total));
    linhas.push('');
    if (pedido.tipoEntrega === 'retirada') {
      linhas.push('Retirada na loja.');
    } else {
      var e = pedido.endereco;
      linhas.push('Entrega em: ' + e.rua + ', ' + e.numero + (e.complemento ? ' - ' + e.complemento : '') + ', ' + e.bairro + ', ' + e.cidade);
    }
    linhas.push('');
    linhas.push('Nome: ' + pedido.cliente);
    linhas.push('WhatsApp: ' + pedido.whatsapp);
    return linhas.join('\n');
  }

  function finalizarPedido() {
    var lines = cartLines();
    if (!lines.length) return;
    var subtotal = cartSubtotal(), discount = cartDiscount(), total = cartTotal();

    var pedido = {
      id: 'PED-' + Date.now().toString().slice(-6),
      cliente: checkout.nome,
      whatsapp: checkout.whatsapp,
      data: new Date().toISOString(),
      itens: lines.map(function (l) { return { produto: l.produto.nome, qtd: l.qtd, preco: l.produto.preco, tamanho: l.tamanho || null }; }),
      subtotal: subtotal,
      desconto: discount,
      cupom: cart.cupom || null,
      total: total,
      status: 'pendente',
      tipoEntrega: checkout.tipoEntrega,
      endereco: checkout.tipoEntrega === 'entrega' ? checkout.endereco : null
    };

    /* grava no mesmo estado que o painel do lojista lê */
    state.pedidos.unshift(pedido);
    if (cart.cupom) {
      var c = findCupom(cart.cupom);
      if (c) { c.usos += 1; c.resultado = (c.resultado || 0) + total; }
    }
    /* baixa o estoque reservado */
    lines.forEach(function (l) {
      var p = produtoById(l.produto.id);
      if (p) p.estoque = Math.max(0, p.estoque - l.qtd);
    });
    saveState();

    var texto = buildWhatsappMessage(pedido);
    var url = 'https://wa.me/' + state.storeWhatsapp + '?text=' + encodeURIComponent(texto);
    window.open(url, '_blank', 'noopener');

    cart = { items: [], cupom: null };
    saveCart();
    renderHeader();
    renderProductGrid();

    renderStatusPanel(pedido, false);

    window.setTimeout(function () {
      var alvo = state.pedidos.filter(function (p) { return p.id === pedido.id; })[0];
      if (alvo) { alvo.status = 'preparo'; saveState(); }
      var painelStatus = document.getElementById('statusDotLabel');
      if (painelStatus) renderStatusPanel(pedido, true);
      toast('success', pedido.tipoEntrega === 'retirada' ? 'Pedido pronto! 🎉' : 'Pedido confirmado! 🚚',
        pedido.tipoEntrega === 'retirada' ? 'Já pode vir buscar na loja.' : 'A loja já está preparando sua entrega.');
    }, 4500);
  }

  function renderStatusPanel(pedido, confirmado) {
    var msgAguardando = pedido.tipoEntrega === 'retirada'
      ? 'Assim que a loja confirmar, avisamos que está pronto para retirada.'
      : 'Assim que a loja confirmar, seu pedido segue para entrega.';
    var msgConfirmado = pedido.tipoEntrega === 'retirada'
      ? 'Pronto! Já pode vir buscar na loja.'
      : 'Confirmado! Sua entrega já está sendo preparada.';

    openModal(
      '<div class="status-panel">' +
      '<div class="status-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></div>' +
      '<h2>Pedido enviado!</h2>' +
      '<p>Abrimos o WhatsApp da loja com os detalhes do pedido <strong>' + pedido.id + '</strong>. Confirme o envio por lá também.</p>' +
      '<div class="status-track" id="statusDotLabel"><span class="status-dot' + (confirmado ? ' is-done' : '') + '"></span>' +
      (confirmado ? msgConfirmado : 'Aguardando confirmação da loja…') + '</div>' +
      renderOrderSummaryHtml(pedido) +
      '<button class="btn btn--solid btn--full" type="button" id="fecharStatus">Continuar comprando</button>' +
      '<p class="form-hint" style="margin-top:10px">' + (confirmado ? '' : msgAguardando) + '</p>' +
      '</div>'
    );
    document.getElementById('fecharStatus').addEventListener('click', closeModal);
  }

  /* =======================================================
     INIT
  ======================================================= */
  renderHeader();
  initFeaturedCarousel();
  renderCategoryNav();
  renderSubcategoryNav();
  var storeSearchInput = document.getElementById('storeSearchInput');
  if (storeSearchInput) {
    storeSearchInput.addEventListener('input', renderProductGrid);
  }
  renderProductGrid();
})();
